    for n in range(1, 20):
        # Check if r_K = (-S_K) % K! becomes constant.
        # r_K is the remainder of -S_K modulo K!.
        # S_K = sum_{j=1}^K j! * j^{n-1}
        S = 0
        r_prev = None
        possible = True
        # We can't check for all K, but let's check for K up to 1000.
        # Actually, if r_K doesn't become constant quickly, it's probably not.
        # Wait, we need r_K = r_{K-1} for all K > K_0.
        # Let's see for which n it's constant for K from 2 to 100.
        constant_since = -1
        for K in range(1, 101):
            # S_K = S_{K-1} + K! * K^{n-1}
            # But we only need r_K = (-S_K) % K!
            # S_K = S_{K-1} + K! * K^{n-1}
            # S_K % K! = S_{K-1} % K!
            # r_K = (-S_{K-1}) % K!

            # Let's just compute S_K and r_K.
            # But S_K grows very fast.
            # Let's use the property r_K = (-S_{K-1}) % K!.
            # No, let's just compute S_K. Python handles large integers.

            # Re-compute S_K from scratch to be safe
            S = 0
            import math
            for j in range(1, K + 1):
                S += math.factorial(j) * (j**(n-1))
            r_K = (-S) % math.factorial(K)

            if r_prev is not None and r_K == r_prev:
                if constant_since == -1:
                    constant_since = K
            else:
                constant_since = -1
            r_prev = r_K

        if constant_since != -1:
            print(f"n={n}: potentially constant")
        else:
            print(f"n={n}: not constant")

