def check_n_poly(n):
    c = [0] * n
    c[n-1] = 1
    for j in range(n-1, 0, -1):
        # c_{j-1} = sum_{i=j}^{n-1} c_i * comb(i, j) * (-1)^{i-j}
        val = 0
        from math import comb
        for i in range(j, n):
            val += c[i] * comb(i, j) * ((-1)**(i-j))
        c[j-1] = val

    # Condition: sum_{i=0}^{n-1} c_i * (-1)^i = 0
    s = 0
    for i in range(n):
        s += c[i] * ((-1)**i)
    return s

for n in range(1, 21):
    print(f"n={n}, sum={check_n_poly(n)}")
